function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
function colLetter(i) { let n = i + 1, out = ''; while (n > 0) { const m = (n - 1) % 26; out = String.fromCharCode(65 + m) + out; n = Math.floor((n - 1) / 26); } return out; }
const TODAY = '2026-09-15';

const meta = $('GET sheet meta').first().json.sheets || [];
let sheetId = null;
for (const sh of meta) { if (s(sh.properties.title) === 'PIPELINE') { sheetId = sh.properties.sheetId; } }
if (sheetId === null) { throw new Error('ABORT: PIPELINE sheetId not found'); }

const pipe = $('GET PIPELINE').first().json.values || [];
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
const ph = (pipe[0] || []).map(s);
const P = {};
['deal_id','startup','investor','email','owner','deal_shared','date_shared','pause','next_action','next_due','match_type','notes','thread_id'].forEach(function (n) { P[n] = ph.indexOf(n); if (P[n] < 0) { throw new Error('ABORT: PIPELINE missing ' + n); } });
const C = {}; ['pause','next_action','next_due','match_type','notes'].forEach(function (n) { C[n] = colLetter(P[n]); });

const rows = [];
for (let r = 1; r < pipe.length; r++) { const row = pipe[r] || [];
  const st = s(row[P.startup]), iv = s(row[P.investor]); if (!st || !iv) { continue; }
  const sent = s(row[P.deal_shared]).toLowerCase() === 'yes';
  const paused = s(row[P.pause]).toLowerCase() === 'yes';
  if (!sent && paused) { continue; }
  rows.push({ row: r + 1, deal_id: s(row[P.deal_id]), startup: st, investor: iv,
    email: s(row[P.email]).split(/[,;\s]+/)[0].toLowerCase(), sent: sent, paused: paused,
    date_shared: s(row[P.date_shared]), next_due: s(row[P.next_due]), notes: s(row[P.notes]) }); }

const g = {};
for (const x of rows) { const k = nz(x.startup) + '|' + (x.email || 'name:' + nz(x.investor)); (g[k] = g[k] || []).push(x); }

const updates = [], deleteRows = [], silenced = [], deleted = [], groups = [];
for (const k of Object.keys(g)) { const grp = g[k]; if (grp.length < 2) { continue; }
  const sent = grp.filter(function (x) { return x.sent; });
  const unsent = grp.filter(function (x) { return !x.sent; });
  let keeper;
  if (sent.length) { sent.sort(function (a, b) { return (a.date_shared || '9999').localeCompare(b.date_shared || '9999') || a.row - b.row; }); keeper = sent[0]; }
  else { unsent.sort(function (a, b) { return (a.next_due || '9999').localeCompare(b.next_due || '9999') || a.row - b.row; }); keeper = unsent[0]; }
  const losers = grp.filter(function (x) { return x.row !== keeper.row; });
  groups.push({ startup: grp[0].startup, inbox: grp[0].email, kept: [keeper.deal_id, keeper.investor, keeper.sent ? 'SENT ' + keeper.date_shared : 'queued ' + keeper.next_due],
    removed: losers.map(function (x) { return [x.deal_id, x.investor, x.sent ? 'SENT ' + x.date_shared : 'queued ' + x.next_due, x.sent ? 'silenced' : 'deleted']; }) });
  for (const x of losers) {
    if (x.sent) {
      const why = 'duplicate - the same deck already went to ' + x.email + ' on ' + (keeper.date_shared || 'an earlier date') + ' as ' + keeper.deal_id;
      updates.push({ range: 'PIPELINE!' + C.pause + x.row, values: [['Yes']] });
      updates.push({ range: 'PIPELINE!' + C.next_action + x.row, values: [['DROPPED - duplicate deal']] });
      updates.push({ range: 'PIPELINE!' + C.next_due + x.row, values: [['']] });
      updates.push({ range: 'PIPELINE!' + C.match_type + x.row, values: [['Duplicate: ' + why]] });
      updates.push({ range: 'PIPELINE!' + C.notes + x.row, values: [[(x.notes ? x.notes + ' | ' : '') + 'DUPLICATE ' + TODAY + ' - ' + why + '; follow-ups stopped, thread kept for the record']] });
      silenced.push([x.row, x.deal_id, x.startup, x.investor, x.date_shared]);
    } else {
      deleteRows.push(x.row);
      deleted.push([x.row, x.deal_id, x.startup, x.investor, x.next_due]);
    } } }

if (silenced.length > 60) { throw new Error('ABORT: ' + silenced.length + ' silences exceeds guard'); }
if (deleteRows.length > 60) { throw new Error('ABORT: ' + deleteRows.length + ' deletions exceeds guard'); }
if (!silenced.length && !deleteRows.length) { throw new Error('ABORT: no duplicates found - nothing to do'); }
if (!updates.length) { updates.push({ range: 'PIPELINE!' + C.pause + '1', values: [['pause']] }); }

// delete bottom-up so earlier row numbers stay valid
deleteRows.sort(function (a, b) { return b - a; });
const deleteRequests = deleteRows.map(function (rn) { return { deleteDimension: { range: { sheetId: sheetId, dimension: 'ROWS', startIndex: rn - 1, endIndex: rn } } }; });

return [{ json: { summary: { duplicate_groups: groups.length, sent_rows_silenced: silenced.length, unsent_rows_deleted: deleteRows.length,
  pipeline_before: pipe.length - 1, expected_after: pipe.length - 1 - deleteRows.length, cell_writes: updates.length, sheetId: sheetId },
  groups: groups, silenced: silenced, deleted: deleted, updates: updates, deleteRequests: deleteRequests, delete_count: deleteRequests.length } }];

